mapper.update:
update kb_retrieve_log set updated_dt = #{updatedDt}, updated_by = #{updatedBy}

    ,feedback_score = #{feedbackScore}


    ,feedback_remark = #{feedbackRemark}

where id = #{id}

mapper.select:
select from kb_retrieve_log where 1=1
order by id desc
limit #{startRow}, #{pageSize}

select query, count(*) as queryCount, COALESCE(avg(avg_similarity), 0) as avgSimilarity from kb_retrieve_log where delete_flag = 1
and tenant_id = #{tenantId}
group by query order by queryCount desc limit #{limit}

select created_by as userId, count(*) as retrieveCount from kb_retrieve_log where delete_flag = 1
and tenant_id = #{tenantId}
group by created_by order by retrieveCount desc limit #{limit}
